def map_tag(tag: str) -> tuple[str, str]:
    """Top-level genre for one tag, and the rule that decided it."""
    t = tag.strip().lower()
    if t in OVERRIDES:
        return OVERRIDES[t], "override"
    if t in EXTRA_TAGS:
        return EXTRA_TAGS[t], "extra_tag"
    for g, rx in _RULES:
        if rx.search(t):
            return g, f"rule:{g}"
    return "other", "default"


