def mb_connect(con=None):
    from lw.ingest.musicbrainz_dump import connect

    return connect(con=con)


def tag_tables(con) -> None:
    """Positive-vote tag links for release groups, releases, recordings and artists."""
    con.execute(f"""create or replace temp table t_rg as select release_group_mbid as id, tag, count
        from read_parquet('{MB}/rg_tags.parquet') where count > 0""")
    for name, table, ent in [("t_release", "release_tag", "release"),
                             ("t_recording", "recording_tag", "recording")]:  # fmt: skip
        con.execute(f"""create or replace temp table {name} as
            select e.gid as id, t.name as tag, try_cast(x.count as int) as count
            from {table} x join {ent} e on e.id = x.{ent} join tag t on t.id = x.tag
            where try_cast(x.count as int) > 0""")


def artist_tags(con) -> None:
    """Artist tags reach a release group through its artist credit (needs artist_credit_name)."""
    # artist tags reach a release group through its artist credit (summed over artists)
    con.execute("""create or replace temp table t_artist as
        select g.gid as id, t.name as tag, sum(try_cast(x.count as int))::int as count
        from release_group g
        join artist_credit_name acn on acn.artist_credit = g.artist_credit
        join artist_tag x on x.artist = acn.artist
        join tag t on t.id = x.tag
        where try_cast(x.count as int) > 0 group by all""")


def write_map(con, path: Path = MAP) -> int:
    """Map every MB genre + EXTRA_TAGS; record rule, MB parents and main-sample weight."""
    genres = [r[0] for r in con.execute("select name from genre").fetchall()]
    parents: dict[str, list[str]] = {}
    try:  # 'subgenre of' links (fetched at P10); optional
        rows = con.execute("""select g0.name, g1.name from l_genre_genre l
            join link k on k.id = l.link join link_type lt on lt.id = k.link_type
            join genre g0 on g0.id = l.entity0 join genre g1 on g1.id = l.entity1
            where lt.name = 'subgenre'""").fetchall()
        for parent, child in rows:  # entity0 is the parent in 'subgenre' links
            parents.setdefault(child, []).append(parent)
    except Exception:  # noqa: BLE001 - table not fetched
        pass
    w = dict(
        con.execute(f"""select tag, count(*) from read_parquet('{TRACKS}') u
        join t_rg on t_rg.id = u.release_group_mbid where u.in_main group by 1""").fetchall()
    )
    rows = []
    for tag in sorted(set(genres) | set(EXTRA_TAGS)):
        g, rule = map_tag(tag)
        rows.append({"tag": tag, "genre": g, "rule": rule, "is_mb_genre": tag in genres,
                     "mb_parents": "; ".join(sorted(parents.get(tag, []))),
                     "main_units": w.get(tag, 0)})  # fmt: skip
    rows.sort(key=lambda r: -r["main_units"])
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "w", newline="") as fh:
        wr = csv.DictWriter(fh, fieldnames=list(rows[0]))
        wr.writeheader()
        wr.writerows(rows)
    return len(rows)


def load_map(con, path: Path = MAP) -> None:
    con.execute(f"""create or replace temp table gmap as
        select tag, genre from read_csv('{path}', header=true, all_varchar=true)
        where genre <> 'ignore'""")


def _winner(con, src: str, out: str) -> None:
    """Per id: genre with most votes over mapped tags (ties by GENRES order) and its share."""
    prio = " ".join(f"when '{g}' then {i}" for i, g in enumerate(GENRES))
    con.execute(f"""create or replace temp table {out} as
        with v as (select id, genre, sum(count) as votes from {src} join gmap using (tag)
                   group by all)
        select id, arg_max(genre, (votes, -(case genre {prio} end))) as genre,
               (max(votes) / sum(votes))::float as share
        from v group by id""")


def hl_labels(con) -> None:
    """Most common label per (MB recording, release) for each AB genre classifier."""
    cols = ", ".join(f"mode({c}) as {c}" for c in HL_MAPS)
    con.execute(f"""create or replace temp table hl as
        select m.recording_mbid_mb as recording_mbid, m.release_mbid, {cols}
        from read_parquet('{MATCHED}') m
        join read_parquet('{HL}/part=*.parquet') h
          using (recording_mbid, part, submission_offset, md5_encoded)
        where m.release_mbid is not null group by all""")


def assign(con) -> dict:
    """Add genre columns to tracks.parquet (idempotent) and build the reference mix."""
    t0 = time.time()
    for ent, src in [("rg", "t_rg"), ("release", "t_release"), ("recording", "t_recording"),
                     ("artist", "t_artist")]:  # fmt: skip
        _winner(con, src, f"w_{ent}")
    hl_labels(con)
    hl_case = lambda c: "case " + c + " " + " ".join(  # noqa: E731
        f"when '{k}' then '{v}'" for k, v in HL_MAPS[c].items()) + " end"  # fmt: skip
    gcols = ["genre", "genre_source", "genre_share", "genre_rg", "genre_artist", "genre_hl",
             "genre_hl_rosamerica", "genre_hl_dortmund", "genre_hl_tzanetakis"]  # fmt: skip
    have = {
        r[0] for r in con.execute(f"describe select * from read_parquet('{TRACKS}')").fetchall()
    }
    excl = f"exclude ({', '.join(c for c in gcols if c in have)})" if have & set(gcols) else ""
    tmp = TRACKS.with_name("tracks.genre.tmp.parquet")
    con.execute(f"""copy (
        select t.* {excl},
          coalesce(rg.genre, rl.genre, rc.genre, ar.genre, {hl_case(HL_CLASSIFIER)}) as genre,
          case when rg.genre is not null then 'rg' when rl.genre is not null then 'release'
               when rc.genre is not null then 'recording' when ar.genre is not null then 'artist'
               when {HL_CLASSIFIER} is not null then 'hl' end as genre_source,
          coalesce(rg.share, rl.share, rc.share, ar.share) as genre_share,
          rg.genre as genre_rg, ar.genre as genre_artist,
          {hl_case(HL_CLASSIFIER)} as genre_hl,
          {hl_case("genre_rosamerica")} as genre_hl_rosamerica,
          {hl_case("genre_dortmund")} as genre_hl_dortmund,
          {hl_case("genre_tzanetakis")} as genre_hl_tzanetakis
        from read_parquet('{TRACKS}') t
        left join w_rg rg on rg.id = t.release_group_mbid
        left join w_release rl on rl.id = t.release_mbid
        left join w_recording rc on rc.id = t.recording_mbid
        left join w_artist ar on ar.id = t.release_group_mbid
        left join hl on hl.recording_mbid = t.recording_mbid and hl.release_mbid = t.release_mbid
    ) to '{tmp}' (format parquet, compression zstd, row_group_size 500000)""")
    shutil.move(tmp, TRACKS)
    con.execute(f"create or replace view tracks as select * from read_parquet('{TRACKS}')")

    # reference mix: MB release groups (Album/EP/Single) by first-release year
    con.execute(f"""create or replace temp table mb_rg as
        select g.release_group_mbid, g.first_release_year as year,
               coalesce(rg.genre, ar.genre) as genre,
               case when rg.genre is not null then 'rg' when ar.genre is not null then 'artist' end as src
        from read_parquet('{MB}/release_group.parquet') g
        left join w_rg rg on rg.id = g.release_group_mbid
        left join w_artist ar on ar.id = g.release_group_mbid
        where g.primary_type in ('Album', 'EP', 'Single')
          and g.first_release_year between {YEARS[0]} and {YEARS[1]}""")
    con.execute(f"""copy (
        with mb as (select year, genre, count(*) n from mb_rg where genre is not null group by all),
        ab as (select year, genre, count(*) n, count(distinct release_group_mbid) n_rg,
                      count(*) filter (where in_main_lossless) n_ll
               from tracks where in_main and genre is not null group by all),
        g as (select distinct year, genre from (select year, genre from mb union all
                                                select year, genre from ab))
        select g.year, g.genre,
          coalesce(mb.n, 0) as mb_rg, coalesce(ab.n, 0) as ab_units,
          coalesce(ab.n_rg, 0) as ab_rg, coalesce(ab.n_ll, 0) as ab_units_lossless,
          coalesce(mb.n, 0) / sum(coalesce(mb.n, 0)) over w as mb_share,
          coalesce(ab.n, 0) / sum(coalesce(ab.n, 0)) over w as ab_unit_share,
          coalesce(ab.n_rg, 0) / sum(coalesce(ab.n_rg, 0)) over w as ab_rg_share,
          coalesce(ab.n_ll, 0) / sum(coalesce(ab.n_ll, 0)) over w as ab_lossless_share,
          mb_share / nullif(ab_unit_share, 0) as weight,
          mb_share / nullif(ab_lossless_share, 0) as weight_lossless
        from g left join mb using (year, genre) left join ab using (year, genre)
        window w as (partition by g.year)
        order by 1, 2) to '{MIX}' (format parquet)""")
    return summarise(con, round(time.time() - t0, 1))


def summarise(con, seconds: float | None = None) -> dict:
    s: dict = {"seconds": seconds}
    s["source_share_main"] = dict(
        con.execute("""select coalesce(genre_source, 'none'),
        round(count(*) / sum(count(*)) over (), 4) from tracks where in_main group by 1
        order by 2 desc""").fetchall()
    )
    s["genre_share_main"] = dict(
        con.execute("""select genre, round(count(*) / sum(count(*)) over (), 4)
        from tracks where in_main and genre is not null group by 1 order by 2 desc""").fetchall()
    )
    s["genre_share_main_lossless"] = dict(
        con.execute("""select genre,
        round(count(*) / sum(count(*)) over (), 4) from tracks
        where in_main_lossless and genre is not null group by 1 order by 2 desc""").fetchall()
    )
    s["mb_rg_coverage"] = dict(
        con.execute("""select coalesce(src, 'none'),
        round(count(*) / sum(count(*)) over (), 4) from mb_rg group by 1 order by 2 desc""").fetchall()
    )
    s["mb_rg_n"] = con.execute("select count(*) from mb_rg").fetchone()[0]
    s["median_genre_share_rg"] = round(con.execute(
        "select median(genre_share) from tracks where in_main and genre_source = 'rg'").fetchone()[0], 4)  # fmt: skip
    # fallback agreement: where a unit has an rg genre, how often do artist / hl agree?
    for col in ["genre_artist", "genre_hl_rosamerica", "genre_hl_dortmund", "genre_hl_tzanetakis"]:
        s[f"agree_rg_{col}"] = round(
            con.execute(f"""select avg((genre_rg = {col})::int)
            from tracks where in_main and genre_rg is not null and {col} is not null""").fetchone()[
                0
            ],
            4,
        )
    return s


def main(argv: list[str] | None = None) -> None:
    import duckdb

    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawTextHelpFormatter)
    ap.add_argument("--write-map", action="store_true", help="regenerate genre_map.csv")
    ap.add_argument("--memory", default="8GB")
    args = ap.parse_args(argv)
    con = duckdb.connect()
    tmp = ROOT / "data" / "interim" / "duckdb_tmp"
    con.execute(f"set memory_limit='{args.memory}'; set temp_directory='{tmp}'")
    con.execute("set preserve_insertion_order=false")
    mb_connect(con)
    tag_tables(con)
    if args.write_map:
        print(f"wrote {write_map(con)} rows to {MAP}")
        return
    artist_tags(con)
    load_map(con)
    s = assign(con)
    SUMMARY.write_text(json.dumps(s, indent=2))
    print(json.dumps(s, indent=2))


if __name__ == "__main__":
    main()
